import{_ as a,o as s,c as t,a2 as n}from"./chunks/framework.RycU2wFZ.js";const m=JSON.parse('{"title":"Payment State Machines, Idempotency, and Recovery","description":"","frontmatter":{},"headers":[],"relativePath":"learn/02-agent-payments/payment-state-and-idempotency.md","filePath":"learn/02-agent-payments/payment-state-and-idempotency.md","lastUpdated":1792595354000}'),i={name:"learn/02-agent-payments/payment-state-and-idempotency.md"};function l(p,e,r,h,d,o){return s(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="payment-state-machines-idempotency-and-recovery" tabindex="-1">Payment State Machines, Idempotency, and Recovery <a class="header-anchor" href="#payment-state-machines-idempotency-and-recovery" aria-label="Permalink to &quot;Payment State Machines, Idempotency, and Recovery&quot;">​</a></h1><h2 id="why-success-and-failure-are-not-enough" tabindex="-1">Why success and failure are not enough <a class="header-anchor" href="#why-success-and-failure-are-not-enough" aria-label="Permalink to &quot;Why success and failure are not enough&quot;">​</a></h2><p>Suppose an agent purchases data for 0.10 USDC. The client sends a payment request and the network connection drops. The only known fact is that the client did not receive a complete response. It does not know whether the request reached the server, payment was verified, a transaction was submitted or confirmed, or the data was delivered.</p><p>A single <code>SUCCESS / FAILED</code> field cannot represent these intermediate and uncertain outcomes. A payment system needs explicit states and rules for moving between them.</p><h2 id="what-is-a-state-machine" tabindex="-1">What is a state machine? <a class="header-anchor" href="#what-is-a-state-machine" aria-label="Permalink to &quot;What is a state machine?&quot;">​</a></h2><p>A state machine describes a process using named states and allowed transitions. A simplified payment intent might move through:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CREATED → AUTHORIZED → VERIFIED → COMPLETED</span></span>
<span class="line"><span>                 ↘ REJECTED</span></span>
<span class="line"><span>                 ↘ EXPIRED</span></span>
<span class="line"><span>                 ↘ CANCELLED</span></span></code></pre></div><p>These names are examples. An implementation must define each state&#39;s precise meaning, entry conditions, valid next states, and recovery behavior. In particular, <code>COMPLETED</code> must not ambiguously mean authorized, delivered, and settled all at once.</p><h2 id="keep-intent-settlement-and-fulfillment-distinct" tabindex="-1">Keep intent, settlement, and fulfillment distinct <a class="header-anchor" href="#keep-intent-settlement-and-fulfillment-distinct" aria-label="Permalink to &quot;Keep intent, settlement, and fulfillment distinct&quot;">​</a></h2><h3 id="payment-intent" tabindex="-1">Payment intent <a class="header-anchor" href="#payment-intent" aria-label="Permalink to &quot;Payment intent&quot;">​</a></h3><p>Tracks the business request and its authorization lifecycle, such as created, authorized, verified, rejected, expired, or cancelled.</p><h3 id="settlement" tabindex="-1">Settlement <a class="header-anchor" href="#settlement" aria-label="Permalink to &quot;Settlement&quot;">​</a></h3><p>Tracks movement of funds. A simplified lifecycle might be:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>NOT_STARTED → SUBMITTED → PENDING → CONFIRMED</span></span>
<span class="line"><span>                              ↘ FAILED</span></span>
<span class="line"><span>                              ↘ REORGED</span></span>
<span class="line"><span>                              ↘ UNKNOWN</span></span></code></pre></div><p><code>UNKNOWN</code> means the system cannot yet determine the result. <code>REORGED</code> means a previously observed confirmation needs rechecking after a chain reorganization. Actual transitions depend on the payment rail.</p><h3 id="fulfillment" tabindex="-1">Fulfillment <a class="header-anchor" href="#fulfillment" aria-label="Permalink to &quot;Fulfillment&quot;">​</a></h3><p>Tracks whether the purchased service was delivered:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>NOT_STARTED → PROCESSING → DELIVERED</span></span>
<span class="line"><span>                        ↘ FAILED</span></span>
<span class="line"><span>                        ↘ RECOVERY_REQUIRED</span></span></code></pre></div><p>For example, payment may be confirmed while an upstream data service times out. In that case settlement is confirmed but fulfillment needs recovery. The system should resume the incomplete service step rather than blindly replaying payment.</p><h2 id="idempotency-prevents-duplicate-effects" tabindex="-1">Idempotency prevents duplicate effects <a class="header-anchor" href="#idempotency-prevents-duplicate-effects" aria-label="Permalink to &quot;Idempotency prevents duplicate effects&quot;">​</a></h2><p>Idempotency means that submitting the same business request again does not create an unintended second effect. If a client times out and retries a 0.10 USDC payment without idempotency controls, the system could charge twice for the same intent.</p><p>An idempotency key identifies one business operation. The same intent should reuse the same key across retries. The server can then return the existing result, continue processing, or reject an invalid duplicate rather than creating a new payment.</p><p>For example, a database can enforce uniqueness within a tenant:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CREATE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> TABLE</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> payment_intent</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">TEXT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> PRIMARY KEY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    tenant_id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">TEXT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    idempotency_key </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">TEXT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    amount </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">TEXT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    status</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> TEXT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    created_at </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">TEXT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    updated_at </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">TEXT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    UNIQUE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (tenant_id, idempotency_key)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>This SQLite example illustrates a uniqueness constraint; it is not a complete production payment schema.</p><h2 id="retry-and-recovery-rules" tabindex="-1">Retry and recovery rules <a class="header-anchor" href="#retry-and-recovery-rules" aria-label="Permalink to &quot;Retry and recovery rules&quot;">​</a></h2><ul><li>Reuse the original idempotency key when retrying the same intent.</li><li>Query or reconcile an unknown settlement before creating another payment.</li><li>Do not equate a timeout with failure.</li><li>Recover fulfillment independently when settlement has already succeeded.</li><li>Make state transitions conditional and auditable so stale workers cannot overwrite newer results.</li></ul><h2 id="key-takeaway" tabindex="-1">Key takeaway <a class="header-anchor" href="#key-takeaway" aria-label="Permalink to &quot;Key takeaway&quot;">​</a></h2><p>Represent what the system knows, including uncertainty. Separate the business intent from settlement and service delivery, and make retries refer to the same intent. This makes recovery safer and prevents ambiguous network failures from turning into duplicate charges.</p>`,29)])])}const k=a(i,[["render",l]]);export{m as __pageData,k as default};
